const raw = $input.first()?.json || {};
const payload = raw.body && typeof raw.body === "object" ? raw.body : raw;

// 1. Validate search_run_id as a positive integer (> 0)
const rawSearchRunId = payload.search_run_id;
if (
  rawSearchRunId === undefined ||
  rawSearchRunId === null ||
  String(rawSearchRunId).trim() === "" ||
  typeof rawSearchRunId === "boolean"
) {
  throw new Error("Invalid search_run_id: must be a positive integer.");
}
const searchRunId = Number(rawSearchRunId);
if (!Number.isInteger(searchRunId) || searchRunId <= 0) {
  throw new Error("Invalid search_run_id: must be a positive integer (> 0).");
}

// 2. Validate required city and business_type
const city = String(payload.city || "").trim();
const businessType = String(payload.business_type || "").trim();
if (!city) {
  throw new Error("Missing required field: city");
}
if (!businessType) {
  throw new Error("Missing required field: business_type");
}

// 3. Validate and constrain max_results to integer in [1, 500] with safe default 20
let maxResults = 20;
if (
  payload.max_results !== undefined &&
  payload.max_results !== null &&
  String(payload.max_results).trim() !== ""
) {
  if (typeof payload.max_results === "boolean") {
    throw new Error("Invalid max_results: must be an integer between 1 and 500.");
  }
  const parsedMax = Number(payload.max_results);
  if (!Number.isInteger(parsedMax) || parsedMax < 1 || parsedMax > 500) {
    throw new Error("Invalid max_results: must be an integer between 1 and 500.");
  }
  maxResults = parsedMax;
}

const testMode = Boolean(
  payload.test_mode === true ||
  city.toUpperCase().startsWith("TEST_ONLY_")
);

// 4. Resolve callback URL from incoming webhook payload and validate without assuming WHATWG URL constructor
const callbackUrl = String(payload.callback_url || "").trim();

if (!callbackUrl) {
  throw new Error(
    "Missing required callback_url: incoming webhook payload must include callback_url."
  );
}

function parseUrlString(rawUrl) {
  if (typeof rawUrl !== "string" || !rawUrl.trim()) {
    return null;
  }
  const str = rawUrl.trim();

  // If WHATWG URL is present in the sandbox runtime, try it first
  if (typeof URL !== "undefined") {
    try {
      const u = new URL(str);
      return {
        protocol: (u.protocol || "").toLowerCase(),
        hostname: (u.hostname || "").toLowerCase().replace(/^\[|\]$/g, ""),
        pathname: u.pathname || "/"
      };
    } catch (_err) {
      return null;
    }
  }

  // Pure JavaScript URI parsing fallback for sandboxed Code node environments
  const protoMatch = str.match(/^(https?):\/\//i);
  if (!protoMatch) {
    return null;
  }
  const protocol = protoMatch[1].toLowerCase() + ":";
  const rest = str.slice(protoMatch[0].length);

  const pathStart = rest.search(/[/\?#]/);
  const authority = pathStart === -1 ? rest : rest.slice(0, pathStart);
  const pathname = pathStart === -1 ? "/" : rest.slice(pathStart).split(/[?#]/)[0] || "/";

  if (!authority) {
    return null;
  }

  let hostname = "";
  if (authority.startsWith("[")) {
    const closeBracket = authority.indexOf("]");
    if (closeBracket === -1) return null;
    hostname = authority.slice(1, closeBracket).toLowerCase();
  } else {
    const colonIndex = authority.indexOf(":");
    hostname = (colonIndex === -1 ? authority : authority.slice(0, colonIndex)).toLowerCase();
  }

  if (!hostname) {
    return null;
  }

  return {
    protocol,
    hostname,
    pathname
  };
}

const parsedCallbackUrl = parseUrlString(callbackUrl);
if (!parsedCallbackUrl) {
  throw new Error("Invalid callback_url format: " + callbackUrl);
}

const callbackHost = (parsedCallbackUrl.hostname || "").toLowerCase();
if (
  ["127.0.0.1", "localhost", "::1", "0.0.0.0", "localhost.localdomain"].includes(callbackHost) ||
  callbackHost.startsWith("127.")
) {
  throw new Error(
    "Invalid callback_url host (" + callbackHost + "): loopback/localhost callback URLs are not permitted."
  );
}

if (!testMode && parsedCallbackUrl.protocol !== "https:") {
  throw new Error(
    "Invalid callback_url protocol (" + parsedCallbackUrl.protocol + "): HTTPS is required in production."
  );
}

if (parsedCallbackUrl.protocol !== "http:" && parsedCallbackUrl.protocol !== "https:") {
  throw new Error("Invalid callback_url protocol: must use http or https.");
}

const execId =
  typeof $execution !== "undefined" && $execution && $execution.id
    ? String($execution.id)
    : "local-exec";

return [
  {
    json: {
      search_run_id: searchRunId,
      city,
      business_type: businessType,
      max_results: maxResults,
      callback_url: callbackUrl,
      test_mode: testMode,
      execution_id: execId
    }
  }
];

const trigger = $('Normalize Trigger Input').first().json;
const placeId = `TEST_PLACE_RUN_${trigger.search_run_id}`;
const title = `[TEST_ONLY] ${trigger.business_type} (${trigger.city})`;

return [
  {
    json: {
      company_name: title,
      title,
      place_id: placeId,
      placeId,
      website: 'https://test-only-verification.example.com',
      address: `100 Test Verification Way, ${trigger.city}`,
      phone: '+1-555-010-9999',
      city: trigger.city,
      business_type: trigger.business_type,
      categories: [trigger.business_type],
      rating: 4.9,
      reviews_count: 42,
      processing_status: 'completed',
      analysis: {
        ai_company_name: title,
        business_summary: 'Controlled test-mode synthesis (Apify, Gemini, and Google Sheets bypassed).',
        personalization_observation: 'Verified webhook -> n8n -> HTTPS callback -> FastAPI pipeline.',
        potential_opportunity: 'End-to-end orchestration verified without external side effects.',
        icebreaker: 'Controlled integration verification complete.',
        confidence: 0.9
      },
      raw_payload: {
        apify: {
          title,
          placeId,
          totalScore: 4.9,
          reviewsCount: 42,
          website: 'https://test-only-verification.example.com',
          address: `100 Test Verification Way, ${trigger.city}`,
          city: trigger.city,
          categories: [trigger.business_type],
          controlled_test_mode: true
        },
        stage1_ai: {
          business_summary: 'Controlled test-mode synthesis (Apify, Gemini, and Google Sheets bypassed).',
          website_status: 'active',
          confidence: 'high'
        },
        stage2_ai: {
          company_name: title,
          personalization_observation: 'Verified webhook -> n8n -> HTTPS callback -> FastAPI pipeline.',
          potential_opportunity: 'End-to-end orchestration verified without external side effects.',
          icebreaker: 'Controlled integration verification complete.'
        },
        ai_company_name: title,
        processing_status: 'completed'
      }
    }
  }
];

const items = $input.all();
const trigger = $('Normalize Trigger Input').first().json;

// Fail explicitly if Apify returned an HTTP/API error object instead of silently producing an empty completed batch
for (const item of items) {
  const data = item.json || {};
  const rawApify = data.raw_apify && typeof data.raw_apify === 'object' ? data.raw_apify : {};
  const statusCode = Number(data.statusCode ?? rawApify.statusCode ?? data.status ?? rawApify.status ?? 0);
  const errObj =
    data.error ||
    data.errorMessage ||
    rawApify.error ||
    rawApify.errorMessage ||
    (data.data && typeof data.data === 'object' && data.data.error ? data.data.error : null);

  if (errObj || (Number.isFinite(statusCode) && statusCode >= 400)) {
    const detail =
      typeof errObj === 'string'
        ? errObj
        : errObj && typeof errObj === 'object'
          ? JSON.stringify(errObj)
          : `HTTP status ${statusCode}`;
    throw new Error(`Apify discovery request failed: ${detail}`);
  }
}

function normalizeWebsite(url) {
  if (!url || typeof url !== 'string' || !url.trim()) return null;
  let raw = url.trim();
  if (!raw.includes('://')) raw = 'http://' + raw;
  try {
    const parsed = new URL(raw);
    let host = (parsed.hostname || '').toLowerCase();
    if (host.startsWith('www.')) host = host.slice(4);
    if (!host || !host.includes('.')) return null;
    const path = (parsed.pathname || '').replace(/\/+$/, '').toLowerCase();
    return `${host}${path}`;
  } catch (_e) {
    return null;
  }
}

function normalizeText(val) {
  if (!val || typeof val !== 'string') return null;
  const cleaned = val.trim().toLowerCase().replace(/\s+/g, ' ');
  return cleaned || null;
}

const seenKeys = new Set();
const results = [];

for (const item of items) {
  const data = item.json || {};
  const rawTitle = data.title ? String(data.title).trim() : '';
  if (!rawTitle) {
    continue;
  }

  const rawApify = data.raw_apify && typeof data.raw_apify === 'object'
    ? { ...data.raw_apify }
    : { ...data };
  delete rawApify.raw_apify;

  const placeId = String(data.placeId || data.place_id || rawApify.placeId || '').trim() || null;
  const website = data.website ? String(data.website).trim() : '';
  const address = data.address ? String(data.address).trim() : '';
  const phone = data.phone ? String(data.phone).trim() : '';
  const city = String(data.city || trigger.city || '').trim();
  const categories = Array.isArray(data.categories) ? data.categories : [];
  const businessType = String(trigger.business_type || categories[0] || '').trim();

  const rawScore = data.totalScore ?? data.rating ?? rawApify.totalScore ?? null;
  const rating = rawScore !== null && rawScore !== undefined && rawScore !== '' ? Number(rawScore) : null;

  const rawReviews = data.reviewsCount ?? data.reviews_count ?? rawApify.reviewsCount ?? null;
  const reviewsCount = rawReviews !== null && rawReviews !== undefined && rawReviews !== '' ? Number(rawReviews) : null;

  // Deduplication priority: 1) placeId, 2) normalized website, 3) normalized company_name + address
  let dedupKey = null;
  const normWeb = normalizeWebsite(website);
  const normName = normalizeText(rawTitle);
  const normAddr = normalizeText(address);

  if (placeId) {
    dedupKey = `place:${placeId.toLowerCase()}`;
  } else if (normWeb) {
    dedupKey = `web:${normWeb}`;
  } else if (normName && normAddr) {
    dedupKey = `name_addr:${normName}|${normAddr}`;
  }

  // If a reliable key exists and was already seen in this execution, skip duplicate.
  // If no reliable key exists (dedupKey === null), retain the record.
  if (dedupKey && seenKeys.has(dedupKey)) {
    continue;
  }
  if (dedupKey) {
    seenKeys.add(dedupKey);
  }

  results.push({
    json: {
      search_run_id: trigger.search_run_id,
      execution_id: trigger.execution_id,
      title: rawTitle,
      company_name: rawTitle,
      placeId,
      place_id: placeId,
      categories,
      business_type: businessType,
      city,
      website,
      address,
      phone,
      totalScore: rating,
      rating,
      reviewsCount,
      reviews_count: reviewsCount,
      raw_apify: rawApify
    }
  });
}

if (results.length === 0) {
  return [
    {
      json: {
        _empty_batch: true,
        search_run_id: trigger.search_run_id,
        execution_id: trigger.execution_id
      }
    }
  ];
}

return results;

