const baseLead = $('Loop Over Items').item.json;

function stripMarkdownJson(raw) {
  if (!raw || typeof raw !== 'string') return '';
  const trimmed = raw.trim();
  const fenced = trimmed.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const firstBrace = fenced.indexOf('{');
  const lastBrace = fenced.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    return fenced.slice(firstBrace, lastBrace + 1);
  }
  return fenced;
}

function parseStructuredOrTextJson(candidate) {
  if (candidate === null || candidate === undefined) return null;
  if (typeof candidate === 'string') {
    const cleaned = stripMarkdownJson(candidate);
    if (!cleaned) return null;
    return JSON.parse(cleaned);
  }
  if (Array.isArray(candidate)) {
    for (const elem of candidate) {
      const parsed = parseStructuredOrTextJson(elem);
      if (parsed && typeof parsed === 'object') return parsed;
    }
    return null;
  }
  if (typeof candidate === 'object') {
    return candidate;
  }
  return null;
}

// 1. Parse Stage 1 AI output safely without throwing (supports text JSON and structured JSON)
let stage1Parsed = null;
let stage1Error = null;
try {
  const stage1NodeJson = $('Basic LLM Chain').item?.json || {};
  if (stage1NodeJson.error) {
    stage1Error = typeof stage1NodeJson.error === 'string' ? stage1NodeJson.error : JSON.stringify(stage1NodeJson.error);
  } else {
    const stage1Candidate =
      stage1NodeJson.output ??
      stage1NodeJson.text ??
      stage1NodeJson.response?.text ??
      stage1NodeJson.response ??
      (stage1NodeJson.business_summary !== undefined || stage1NodeJson.confidence !== undefined
        ? stage1NodeJson
        : null);
    if (stage1Candidate !== null && stage1Candidate !== undefined && stage1Candidate !== '') {
      const parsed = parseStructuredOrTextJson(stage1Candidate);
      if (parsed && typeof parsed === 'object') {
        stage1Parsed = parsed;
      } else {
        stage1Error = 'Stage 1 AI output is not a valid JSON object';
      }
    } else {
      stage1Error = 'Stage 1 AI output missing';
    }
  }
} catch (err) {
  stage1Error = `Stage 1 JSON parse error: ${err.message}`;
}

// 2. Parse Stage 2 AI output safely without throwing (supports structured JSON object and text JSON)
let stage2Parsed = null;
let stage2Error = null;
try {
  const s2 = $json || {};
  if (s2.error) {
    stage2Error = typeof s2.error === 'string' ? s2.error : JSON.stringify(s2.error);
  } else {
    const hasTopLevelStage2Fields =
      typeof s2.company_name === 'string' ||
      typeof s2.personalization_observation === 'string' ||
      typeof s2.potential_opportunity === 'string' ||
      typeof s2.icebreaker === 'string';

    const part0 = s2.content?.parts?.[0] ?? s2.candidates?.[0]?.content?.parts?.[0] ?? null;
    const partCandidate =
      part0 && typeof part0 === 'object'
        ? part0.text !== undefined
          ? part0.text
          : part0.json !== undefined
            ? part0.json
            : part0
        : part0;

    const stage2Candidate =
      partCandidate ??
      s2.output ??
      s2.text ??
      s2.response?.text ??
      s2.response ??
      s2.data ??
      s2.message?.content ??
      (hasTopLevelStage2Fields ? s2 : null);

    if (stage2Candidate !== null && stage2Candidate !== undefined && stage2Candidate !== '') {
      const candidate = parseStructuredOrTextJson(stage2Candidate);
      if (candidate && typeof candidate === 'object') {
        const requiredFields = [
          'company_name',
          'personalization_observation',
          'potential_opportunity',
          'icebreaker'
        ];
        const missing = requiredFields.filter(
          (f) => typeof candidate[f] !== 'string' || !candidate[f].trim()
        );
        if (missing.length > 0) {
          stage2Error = `Missing or empty Stage 2 AI fields: ${missing.join(', ')}`;
        }
        stage2Parsed = candidate;
      } else {
        stage2Error = 'Stage 2 Gemini response is not a valid JSON object';
      }
    } else {
      stage2Error = 'Stage 2 Gemini response text missing';
    }
  }
} catch (err) {
  stage2Error = `Stage 2 JSON parse error: ${err.message}`;
}

const CONFIDENCE_MAP = { low: 0.3, medium: 0.6, high: 0.9 };
let confidenceScore = null;
if (stage1Parsed && stage1Parsed.confidence !== undefined && stage1Parsed.confidence !== null) {
  const rawConf = String(stage1Parsed.confidence).trim().toLowerCase();
  if (CONFIDENCE_MAP[rawConf] !== undefined) {
    confidenceScore = CONFIDENCE_MAP[rawConf];
  } else if (!Number.isNaN(Number(rawConf))) {
    const num = Number(rawConf);
    if (num >= 0 && num <= 1) confidenceScore = num;
  }
}

const businessSummary = stage1Parsed && typeof stage1Parsed.business_summary === 'string'
  ? stage1Parsed.business_summary.trim()
  : null;
const aiCompanyName = stage2Parsed && typeof stage2Parsed.company_name === 'string'
  ? stage2Parsed.company_name.trim()
  : null;
const personalizationObservation = stage2Parsed && typeof stage2Parsed.personalization_observation === 'string'
  ? stage2Parsed.personalization_observation.trim()
  : null;
const potentialOpportunity = stage2Parsed && typeof stage2Parsed.potential_opportunity === 'string'
  ? stage2Parsed.potential_opportunity.trim()
  : null;
const icebreaker = stage2Parsed && typeof stage2Parsed.icebreaker === 'string'
  ? stage2Parsed.icebreaker.trim()
  : null;

const hasValidAnalysis = Boolean(
  businessSummary ||
  personalizationObservation ||
  potentialOpportunity ||
  icebreaker ||
  confidenceScore !== null
);

const processingStatus = hasValidAnalysis && !stage2Error ? 'completed' : 'partial_ai_failure';

const analysisPayload = hasValidAnalysis
  ? {
      ai_company_name: aiCompanyName,
      business_summary: businessSummary,
      personalization_observation: personalizationObservation,
      potential_opportunity: potentialOpportunity,
      icebreaker,
      confidence: confidenceScore,
      stage1_analysis: stage1Parsed,
      stage2_analysis: stage2Parsed,
      error: stage1Error || stage2Error || null
    }
  : null;

return {
  json: {
    // Canonical company_name ALWAYS comes from Apify title
    company_name: baseLead.title,
    title: baseLead.title,
    place_id: baseLead.placeId || baseLead.place_id || null,
    website: baseLead.website || null,
    address: baseLead.address || null,
    phone: baseLead.phone || null,
    city: baseLead.city,
    business_type: baseLead.business_type,
    categories: baseLead.categories || [],
    rating: baseLead.rating ?? null,
    reviews_count: baseLead.reviews_count ?? null,
    processing_status: processingStatus,
    // Flat convenience fields for optional Google Sheets export
    ai_company_name: aiCompanyName || '',
    business_summary: businessSummary || '',
    personalization_observation: personalizationObservation || '',
    potential_opportunity: potentialOpportunity || '',
    icebreaker: icebreaker || '',
    confidence: confidenceScore,
    // Structured analysis & full raw_payload for FastAPI callback
    analysis: analysisPayload,
    raw_payload: {
      apify: baseLead.raw_apify,
      stage1_ai: stage1Parsed || { error: stage1Error },
      stage2_ai: stage2Parsed || { error: stage2Error },
      ai_company_name: aiCompanyName,
      processing_status: processingStatus
    }
  }
};

// Restore the canonical lead item from Code in JavaScript1 before returning to Loop Over Items
// so Google Sheets output metadata or optional export errors never corrupt the execution-local batch.
return [
  {
    json: $('Code in JavaScript1').item.json
  }
];

// Execution-isolated batch aggregation: reads only the items emitted by Loop Over Items (done branch)
// for the current workflow execution context.
const trigger = $('Normalize Trigger Input').first().json;
const rawItems = $input.all();

const leads = [];
for (const item of rawItems) {
  const data = item.json || {};
  if (data._empty_batch) {
    continue;
  }
  if (!data.company_name && !data.title) {
    continue;
  }
  leads.push({
    company_name: data.company_name || data.title,
    title: data.title || data.company_name,
    place_id: data.place_id || data.placeId || null,
    website: data.website || null,
    address: data.address || null,
    phone: data.phone || null,
    city: data.city || trigger.city,
    business_type: data.business_type || trigger.business_type,
    categories: data.categories || [],
    rating: data.rating ?? null,
    reviews_count: data.reviews_count ?? null,
    processing_status: data.processing_status || 'completed',
    analysis: data.analysis || null,
    raw_payload: data.raw_payload || {
      apify: data.raw_apify || {},
      stage1_ai: null,
      stage2_ai: null
    }
  });
}

return [
  {
    json: {
      callback_url: trigger.callback_url,
      payload: {
        search_run_id: trigger.search_run_id,
        execution_id: trigger.execution_id,
        status: 'completed',
        leads
      }
    }
  }
];
